function drawPerson(x,y,emoji,shirt='#45634c',scale=1){ctx.fillStyle='#61745355';ctx.beginPath();ctx.ellipse(x,y+8*scale,9*scale,4*scale,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=shirt;roundRect(x-6*scale,y-7*scale,12*scale,17*scale,5*scale,shirt);ctx.fillStyle='#e9b18f';ctx.beginPath();ctx.arc(x,y-12*scale,7*scale,0,Math.PI*2);ctx.fill();ctx.textAlign='center';ctx.font=`${14*scale}px system-ui`;ctx.fillText(emoji,x,y-9*scale)}
function drawInterior(){
 const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#f3e7d4');g.addColorStop(1,'#e6d9c5');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // room boards
 ctx.fillStyle='#d5b999';ctx.fillRect(0,H*.68,W,H*.32);ctx.strokeStyle='#c8ad8f';ctx.lineWidth=1;for(let y=H*.69;y<H;y+=25){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}for(let x=45;x<W;x+=105){ctx.beginPath();ctx.moveTo(x,H*.68);ctx.lineTo(x,H);ctx.stroke()}
 // walls and wallpaper
 ctx.fillStyle='#fbf4e8';ctx.fillRect(0,0,W,H*.68);ctx.fillStyle='#e4cbb0';ctx.fillRect(0,H*.65,W,H*.045);ctx.fillStyle='#cba982';ctx.fillRect(0,H*.68,W,7);
 for(let x=22;x<W;x+=47)for(let y=20;y<H*.63;y+=41){ctx.fillStyle='#eadbc8';ctx.beginPath();ctx.arc(x,y,1.3,0,Math.PI*2);ctx.fill()}
 // window
 roundRect(W*.12,H*.1,W*.22,H*.29,8,'#a9d8d6','#fff');ctx.strokeStyle='#fff';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(W*.23,H*.1);ctx.lineTo(W*.23,H*.39);ctx.moveTo(W*.12,H*.245);ctx.lineTo(W*.34,H*.245);ctx.stroke();ctx.fillStyle='#d3e2be';ctx.fillRect(W*.12,H*.36,W*.22,H*.04);
 // door
 roundRect(W*.81,H*.27,W*.13,H*.4,7,'#a97550','#f3d9b8');ctx.fillStyle='#f6d991';ctx.beginPath();ctx.arc(W*.91,H*.48,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c2a883';ctx.fillRect(W*.78,H*.665,W*.19,7);
 // area rug
 ctx.fillStyle='#e7d995';ctx.beginPath();ctx.ellipse(W*.52,H*.79,W*.25,H*.15,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fbf0c1';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(W*.52,H*.79,W*.22,H*.125,0,0,Math.PI*2);ctx.stroke();
 const home=state.homes[state.selectedHome]||state.homes[0];
 home.items.forEach((f,i)=>{const x=f.x*W,y=f.y*H;ctx.fillStyle=f.color;roundRect(x-W*.06,y-H*.045,W*.12,H*.09,9,f.color,'#ffffffaa');ctx.font=`${Math.max(20,Math.min(W,H)*.055)}px system-ui`;ctx.textAlign='center';ctx.fillText(f.emoji,x,y+7);ctx.fillStyle='#fff9';roundRect(x-W*.06,y+H*.027,W*.12,5,3,'#fff9')});
 // character inside
 const p=state.character;drawPerson(p.x*W,p.y*H,state.avatar,'#45634c',1.25);
 if(state.tool==='furnish'&&selectedItem&&hover){ctx.globalAlpha=.58;ctx.fillStyle=selectedItem.color;roundRect(hover.x-W*.06,hover.y-H*.045,W*.12,H*.09,9,selectedItem.color);ctx.font=`${Math.max(20,Math.min(W,H)*.055)}px system-ui`;ctx.textAlign='center';ctx.fillText(selectedItem.emoji,hover.x,hover.y+7);ctx.globalAlpha=1}
 ctx.fillStyle='#857d6c';ctx.font='12px system-ui';ctx.textAlign='left';ctx.fillText('SUNROOM   ·   A LITTLE PLACE TO CALL YOURS',20,24);
}
function coords(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function nearestHome(x,y){for(let i=0;i<state.homes.length;i++){const r=homeRect(state.homes[i]);if(x>=r.x&&x<=r.x+r.w&&y>=r.y&&y<=r.y+r.h)return i}return -1}
function openView(view){state.view=view;state.tool='select';selectedItem=null;renderUI();draw();save()}
function doAction(action){switch(action){case'eat':state.needs.hunger=Math.min(100,state.needs.hunger+38);state.money=Math.max(0,state.money-8);toast('A tasty little snack! −8 coins');break;case'sleep':state.needs.energy=Math.min(100,state.needs.energy+52);state.minute+=120;toast('A lovely rest. Feeling refreshed!');break;case'social':state.needs.social=Math.min(100,state.needs.social+32);state.needs.hunger=Math.max(0,state.needs.hunger-3);toast('A friendly chat brightened your day!');break;case'work':if(state.day===state.lastWorkDay){toast('You already worked a shift today. Time to unwind!');break}if(state.minute%1440<9*60){toast('Your shift starts at 9am — enjoy the morning!');break}state.money+=jobs[state.job].pay;state.lastWorkDay=state.day;state.needs.energy=Math.max(0,state.needs.energy-16);state.needs.hunger=Math.max(0,state.needs.hunger-12);state.needs.social=Math.max(0,state.needs.social-5);state.minute+=240;toast(`Shift complete! You earned ☼${jobs[state.job].pay}.`);break;case'character':characterModal();return}state.needs.hygiene=Math.max(0,state.needs.hygiene-2);renderUI();draw();save()}
function characterModal(){const root=$('#modalRoot');root.innerHTML=`<div class="modal-back"><div class="modal"><h2>Make yourself at home</h2><p>Your little life starts with you. Pick a look, a name, and a job.</p><div class="formrow"><label>YOUR NAME</label><input id="charName" maxlength="18" value="${state.name}"></div><div class="formrow"><label>CHOOSE YOUR LOOK</label><div class="choice-row">${['🙂','😊','😎','🤓','🥰','😌'].map(e=>`<button class="choice ${e===state.avatar?'sel':''}" data-avatar="${e}">${e}</button>`).join('')}</div></div><div class="formrow"><label>YOUR DAY JOB</label><select id="charJob">${jobs.map((j,i)=>`<option value="${i}" ${state.job===i?'selected':''}>${j.icon} ${j.name} — ☼${j.pay}/shift</option>`).join('')}</select></div><button class="start-btn" id="saveCharacter">Save my little life</button></div></div>`;
 root.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>{root.querySelectorAll('.choice').forEach(x=>x.classList.remove('sel'));b.classList.add('sel')});root.querySelector('.modal-back').onclick=e=>{if(e.target.classList.contains('modal-back'))root.innerHTML=''};$('#saveCharacter').onclick=()=>{state.name=$('#charName').value.trim()||'Neighbor';state.job=Number($('#charJob').value);state.avatar=root.querySelector('.choice.sel')?.dataset.avatar||'🙂';state.started=true;root.innerHTML='';renderUI();draw();save();toast(`Welcome home, ${state.name}!`)};
}
function initialModal(){if(!state.started)characterModal()}
function buildHomeAt(index){const l=getLayout(),cell=homeRect({x:index%3,y:Math.floor(index/3)});if(state.homes.length>=6){toast('Every plot is full — what a lovely neighborhood!');return}if(state.money<450){toast('You need ☼450 to build a new home.');return}if(state.homes.some(h=>h.x===index%3&&h.y===Math.floor(index/3))){toast('That plot already has a home!');return}state.money-=450;state.homes.push({x:index%3,y:Math.floor(index/3),owner:false,items:[]});state.selectedHome=state.homes.length-1;state.tool='select';state.view='town';toast('A new neighbor moved in! −☼450');renderUI();draw();save()}
canvas.addEventListener('pointermove',e=>{hover=coords(e);if(drag){state.character.x=Math.max(.04,Math.min(.96,hover.x/W));state.character.y=Math.max(.1,Math.min(.94,hover.y/H));draw()}else draw()});
canvas.addEventListener('pointerup',e=>{if(drag){drag=null;save();return}const p=coords(e);if(state.view==='home'){
 if(p.x>W*.79&&p.y>H*.24&&p.y<H*.72){openView('town');return}
 if(state.tool==='furnish'&&selectedItem){const item=selectedItem;state.money-=item.cost;const home=state.homes[state.selectedHome];home.items.push({id:item.id,emoji:item.emoji,color:item.color,x:Math.max(.09,Math.min(.72,p.x/W)),y:Math.max(.46,Math.min(.9,p.y/H))});selectedItem=null;state.tool='select';toast(`${item.name} placed!`);renderUI();draw();save();return}
 state.character.dest={x:p.x/W,y:p.y/H};draw();return}
 const hit=nearestHome(p.x,p.y);if(state.tool==='build'){const l=getLayout();let plot=-1;for(let row=0;row<2;row++)for(let col=0;col<3;col++){const r=homeRect({x:col,y:row});if(p.x>=r.x&&p.x<=r.x+r.w&&p.y>=r.y&&p.y<=r.y+r.h)plot=row*3+col}if(plot>=0)buildHomeAt(plot);return}
 if(hit>=0){state.selectedHome=hit;if(state.homes[hit].owner){openView('home')}else{state.character.dest={x:p.x/W,y:p.y/H};toast('A friendly neighbor lives here! Say hello to brighten your day.');state.needs.social=Math.min(100,state.needs.social+8);renderUI();draw();save()}return}
 state.character.dest={x:p.x/W,y:p.y/H};state.needs.energy=Math.max(0,state.needs.energy-.3);draw();
});
canvas.addEventListener('pointerdown',e=>{if(state.view!=='home')return;const p=coords(e),cx=state.character.x*W,cy=state.character.y*H;if(Math.hypot(p.x-cx,p.y-cy)<30){drag=true;canvas.setPointerCapture(e.pointerId)}});

