canvas.addEventListener('pointerdown',e=>{if(state.view!=='home')return;const p=coords(e),cx=state.character.x*W,cy=state.character.y*H;if(Math.hypot(p.x-cx,p.y-cy)<30){drag=true;canvas.setPointerCapture(e.pointerId)}});
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.view==='home'&&!state.homes[state.selectedHome]?.owner){state.selectedHome=0}openView(b.dataset.view)}));
$$('[data-action]').forEach(b=>b.addEventListener('click',()=>doAction(b.dataset.action)));
$('#buildHome').onclick=()=>{state.view='town';state.tool='build';selectedItem=null;renderUI();draw();toast('Choose any open plot to build your next home')};
$('#furnish').onclick=()=>{if(state.view!=='home'){state.view='home';state.selectedHome=state.homes.findIndex(h=>h.owner);if(state.selectedHome<0)state.selectedHome=0}state.tool='furnish';selectedItem=null;renderUI();draw();$('#catalogHint').textContent='Pick an item'};
$('#enterHome').onclick=()=>openView('home');$('#townView').onclick=()=>openView('town');
$('#speedBtn').onclick=()=>{state.paused=!state.paused;$('#speedBtn').textContent=state.paused?'▶ Play':'⏸ Pause';save()};
setInterval(()=>{if(state.paused)return;state.minute+=5;if(state.minute>=1440){state.minute=0;state.day++;state.lastWorkDay=0;toast('A brand new day in Maplewood!')}if(state.minute%60===0){state.needs.hunger=Math.max(0,state.needs.hunger-.8);state.needs.energy=Math.max(0,state.needs.energy-.45);state.needs.hygiene=Math.max(0,state.needs.hygiene-.25);state.needs.social=Math.max(0,state.needs.social-.2)}if(state.character.dest){const dx=state.character.dest.x-state.character.x,dy=state.character.dest.y-state.character.y,dist=Math.hypot(dx,dy);if(dist<.012)state.character.dest=null;else{state.character.x+=dx/dist*.008;state.character.y+=dy/dist*.008}}renderUI();draw();save()},1800);
renderUI();resize();initialModal();
})();
</script>
